/* Prepared bird frames: no runtime drawing or artwork processing. */
(()=>{
const atlas='data:image/webp;base64,';
window.RosevilleBird=(host)=>{
 if(host.dataset.birdMounted)return;host.dataset.birdMounted='1';
 const frame=host.querySelector('.sign-frame'),el=document.createElement('button');el.type='button';el.className='sign-bird-light';el.setAttribute('aria-label','Nudge the bird sideways');
 Object.assign(el.style,{position:'absolute',width:'96px',height:'96px',padding:'0',border:'0',backgroundColor:'transparent',backgroundImage:`url(${atlas})`,backgroundSize:'768px 384px',backgroundRepeat:'no-repeat',boxShadow:'none',transformOrigin:'48px 78px',zIndex:'8',display:'none',touchAction:'manipulation'});host.appendChild(el);
 let state='absent',keys=new Set(),timers=new Set(),raf=0,visible=true,x=0,hop=false,idleTimer=0;
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const night=()=>document.body.classList.contains('night');
 const later=(f,ms)=>{const id=setTimeout(()=>{timers.delete(id);if(host.isConnected&&!document.hidden&&visible)f();},ms);timers.add(id);return id;};
 const cancel=()=>{timers.forEach(clearTimeout);timers.clear();cancelAnimationFrame(raf);raf=0;};
 function sprite(i){el.style.backgroundPosition=`${-(i%8)*96}px ${-Math.floor(i/8)*96}px`;}
 function place(px=x,py=0){const scale=frame.offsetWidth/570,left=frame.offsetLeft+59*scale,top=frame.offsetTop;el.style.left=(left+px*scale-48)+'px';el.style.top=(top+py*scale-78)+'px';el.style.transform=`scale(${scale})`;}
 const resize=new ResizeObserver(()=>place());resize.observe(frame);
 function animate(duration,update,done){cancelAnimationFrame(raf);const start=performance.now();let last=-100;function tick(now){if(!host.isConnected||document.hidden||!visible){raf=0;return;}const t=Math.min(1,(now-start)/duration);if(now-last>32||t===1){update(t,now-start);last=now;}if(t<1)raf=requestAnimationFrame(tick);else{raf=0;done?.();}}raf=requestAnimationFrame(tick);}
 function reset(){cancel();state='absent';keys.clear();el.style.display='none';x=0;}
 function idle(){if(state!=='perched')return;const seq=[18,19,18,17,18,19,14,18],i=Math.floor(Math.random()*seq.length);sprite(seq[i]);place();later(idle,650+Math.random()*1550);}
 function tail(){if(state!=='perched'||hop)return;let i=0;const next=()=>{if(state!=='perched')return;sprite(20+i++);if(i<12)later(next,65);else{sprite(18);later(tail,5500+Math.random()*6500);}};next();}
 function departure(){if(state!=='perched')return;cancel();state='leaving';const from=x;animate(reduced?1:1900,(t,ms)=>{sprite(Math.floor(ms/24)%12);place(from+t*700,-Math.sin(t*Math.PI*.8)*120-10);},reset);}
 function armDeparture(){clearTimeout(idleTimer);idleTimer=later(departure,45000);}
 function perch(){state='perched';sprite(18);place();later(idle,750);later(tail,3200);armDeparture();}
 function arrive(){if(state!=='absent'||night()||!visible||document.hidden)return;state='arriving';el.style.display='block';animate(reduced?1:2100,(t,ms)=>{sprite(t>.85?12:Math.floor(ms/24)%12);place(-190*(1-t),-90*(1-t)-Math.sin(t*Math.PI)*65);},perch);}
 el.addEventListener('click',e=>{e.stopPropagation();if(state!=='perched'||hop)return;hop=true;armDeparture();const from=x,to=x>10?-8:24;animate(reduced?1:330,t=>{sprite(18);x=from+(to-from)*t;place(x,-Math.sin(Math.PI*t)*9);},()=>{hop=false;place();});});
 const onSign=()=>departure();frame.addEventListener('click',onSign);
 const onBloom=e=>{keys.add(e.detail.key);if(keys.size>=2)later(arrive,1600);};host.addEventListener('roseville:bloom',onBloom);
 const intersection=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(!visible){cancel();if(state==='arriving'||state==='leaving')reset();}else if(state==='perched'){idle();later(tail,3500);armDeparture();}},{rootMargin:'100px'});intersection.observe(host);
 const visibility=()=>{if(document.hidden)cancel();else if(visible&&state==='perched'){idle();later(tail,3500);armDeparture();}};document.addEventListener('visibilitychange',visibility);
 const theme=new MutationObserver(()=>{if(night())reset();});theme.observe(document.body,{attributes:true,attributeFilter:['class']});
 const detach=new MutationObserver(()=>{if(host.isConnected)return;cancel();resize.disconnect();intersection.disconnect();theme.disconnect();detach.disconnect();document.removeEventListener('visibilitychange',visibility);});detach.observe(document.getElementById('main'),{childList:true});place();
};
window.dispatchEvent(new Event('roseville:bird-ready'));
})();
